function makeStringGood(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) count[ch.charCodeAt(0) - 97]++;
  const most = Math.max(...count);
  let best = s.length;
  for (let target = 1; target <= most; target++) {
    const dp = new Array(27).fill(0);
    for (let i = 1; i <= 26; i++) {
      const have = count[i - 1];
      const alone = have >= target ? have - target : Math.min(have, target - have);
      dp[i] = dp[i - 1] + alone;
      if (i >= 2 && have < target) {
        const before = count[i - 2];
        const spare = before >= target ? before - target : before;
        dp[i] = Math.min(dp[i], dp[i - 2] + Math.max(spare, target - have));
      }
    }
    best = Math.min(best, dp[26]);
  }
  return best;
}

