function makeStringGood(s) {
  const n = s.length;
  const count = new Array(26).fill(0);
  for (const ch of s) count[ch.charCodeAt(0) - 97]++;
  let best = Infinity;
  // Every final count is 0 or t. For each t, search every way of pushing copies forward letter by letter:
  // cost[m] is the cheapest cost so far when m copies are being turned into the next letter.
  for (let t = 1; t <= n; t++) {
    let cost = new Array(n + 1).fill(Infinity);
    cost[0] = 0;
    for (let letter = 0; letter < 26; letter++) {
      const next = new Array(n + 1).fill(Infinity);
      for (let incoming = 0; incoming <= n; incoming++) {
        if (cost[incoming] === Infinity) continue;
        const available = count[letter] + incoming;
        const limit = letter === 25 ? 0 : available;
        for (let moved = 0; moved <= limit; moved++) {
          const kept = available - moved;
          const settle = Math.min(kept, Math.abs(kept - t));
          next[moved] = Math.min(next[moved], cost[incoming] + moved + settle);
        }
      }
      cost = next;
    }
    best = Math.min(best, cost[0]);
  }
  return best;
}

