function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 8000 + Math.floor(rand() * 2001) : 3 + Math.floor(rand() * 10);
  // A run of neighbouring letters with uneven weights, sometimes ending at 'z'.
  const width = 1 + Math.floor(rand() * (large ? 26 : 5));
  const first = rand() < 0.2 ? 26 - width : Math.floor(rand() * (27 - width));
  const weights = Array.from({ length: width }, () => rand() * rand() + 0.05);
  const total = weights.reduce((a, b) => a + b, 0);
  let s = '';
  for (let k = 0; k < n; k++) {
    let r = rand() * total, letter = 0;
    while (letter < width - 1 && r >= weights[letter]) r -= weights[letter++];
    s += String.fromCharCode(97 + first + letter);
  }
  return [s];
}
